#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

vec3 pow3(vec3 x, float y){
  vec3 t = vec3(0.0);
  t.x = pow(x.x, y);
  t.y = pow(x.y, y);
  t.z = pow(x.z, y);

  return t;
}

vec2 rotateVector2(vec2 v, float angle) {
  float a = radians(angle);
  float cosA = cos(a);
  float sinA = sin(a);
  return vec2(
    cosA * v.x + sinA * v.y,
    -sinA * v.x + cosA * v.y
  );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  //ring
  float rad = max(iResolution.x, iResolution.y) * 0.5;
  float dis = distance(iResolution.xy/2.0, gl_FragCoord.xy) / rad;
  float disx = sin(pow(dis,1.0/5.0) * 15.0 - iTime * 0.5);

  //uv
  vec2 uv = gl_FragCoord.xy / iResolution.xy;
  float uvb = iResolution.x / iResolution.y;
  vec2 uvx = rotateVector2(uv - 0.5, disx *  -50.0+100.0*(1.0-dis));

  //angle
  float fan = atan(uvx.y, uvx.x * uvb) / 6.28 + 0.5;

  //fan
  vec3 time3 = vec3(iTime*0.07, iTime*0.05, iTime*0.03);
  vec3 crx = fract(vec3(fan) - time3) / 1.0;
  vec3 crxn = 1.0 - crx;
  vec3 pcrxn = pow3(crxn, 5.0);
  vec3 pcrx = pow3(crx, 5.0)+pcrxn;


  float xx = disx * fan;
  float powdis = pow(dis, 1.0);


  vec3 color = pcrx * powdis;
  vec3 fcolor = vec3(color.x, color.y * 0.0, color.z * (1.0 - color.x));
  fragColor = vec4(fcolor,1.0);
}
